(function(){
'use strict';
const FLOW='20260915-chat-freeze-fix-v2';
const OPENING='איזה כיף 🏖️\nספרו לי קצת על החופשה שאתם מתכננים — לאן תרצו לטוס, מתי ומי נוסע.\nואם עדיין לא החלטתם לאן — אפשר גם לתת לי להמליץ לכם 😊';
const RULES='אריאלה מנהלת שיחה טבעית כמו סוכנת נסיעות ולא שאלון. אין להציג קודים פנימיים, true/false או enum, ואין לשאול שוב מידע שכבר נמסר. בחופשה רגילה: קודם יעד/בחירת אריאלה, מועד ומי נוסע; אחר כך תקציב, כבודה וישיר/קונקשן. רק לאחר השלמת פרטי הטיסה שואלים על בניית הטיול. אין לשאול אוטומטית על גמישות או משך.';
function isTrip(){return !!document.getElementById('tripWizard')||location.pathname.indexOf('/trip/new')===0;}
function removeLegacy(){document.querySelectorAll('#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar').forEach(x=>x.remove());const w=document.getElementById('tripWizard');if(w&&w.style.display!=='none')w.style.display='none';}
function style(){if(document.getElementById('ariella-chat-rebuild-style'))return;const s=document.createElement('style');s.id='ariella-chat-rebuild-style';s.textContent=`#tripWizard,#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar{display:none!important}#ariellaDesktopChat{width:min(1280px,92%);margin:18px auto 40px;direction:rtl;font-family:Arial,"Segoe UI",sans-serif}#ariellaDesktopChat .ac-shell{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,.85fr);gap:22px}#ariellaDesktopChat .ac-chat,#ariellaDesktopChat .ac-summary{background:#fffaf2;border:1px solid rgba(201,154,63,.38);border-radius:22px;overflow:hidden}#ariellaDesktopChat .ac-chat{height:min(650px,calc(100vh - 150px));min-height:520px;display:flex;flex-direction:column}#ariellaDesktopChat .ac-head{display:flex;align-items:center;gap:10px;padding:10px 14px;background:linear-gradient(135deg,#102b30,#18373a);color:#fff}#ariellaDesktopChat .ac-avatar{width:52px;height:52px;flex:0 0 52px;border:2px solid #fff3cf;border-radius:50%;background:#17353a}#ariellaDesktopChat .ac-head-copy{min-width:0;flex:1}#ariellaDesktopChat .ac-head-copy strong{display:block;font-size:16px;white-space:nowrap}#ariellaDesktopChat .ac-online{margin-inline-start:auto;font-size:13px}#ariellaDesktopChat .ac-messages{flex:1;min-height:0;padding:18px 14px;display:flex;flex-direction:column;gap:12px;overflow-y:auto;background:linear-gradient(180deg,#fffdf8,#fbf5e9)}#ariellaDesktopChat .ac-row{display:flex;gap:8px;align-items:flex-start}#ariellaDesktopChat .ac-row.user{justify-content:flex-start;flex-direction:row-reverse}#ariellaDesktopChat .ac-bubble{max-width:84%;padding:11px 13px;border-radius:14px;background:#fff;border:1px solid #eadfc8;white-space:pre-line;line-height:1.55}#ariellaDesktopChat .ac-row.user .ac-bubble{background:#dff3f5;border-color:#b7dde1}#ariellaDesktopChat .ac-mini-avatar{width:34px;height:34px;flex:0 0 34px;border-radius:50%;border:1px solid #d6bf86;background:#17353a}#ariellaDesktopChat .ac-compose{padding:10px;border-top:1px solid #eadfc8;background:#fff;display:flex;gap:10px}#ariellaDesktopChat textarea{flex:1;min-height:48px;max-height:120px;border:1px solid #d9cdb8;border-radius:14px;padding:12px;font:inherit;resize:none}#ariellaDesktopChat .ac-send{height:48px;min-width:68px;border:0;border-radius:13px;background:#0b8f9c;color:#fff;font-weight:800}#ariellaDesktopChat .ac-summary{padding:18px}#ariellaDesktopChat .ac-detail{padding:9px 0;border-bottom:1px solid #eee5d5}#ariellaDesktopChat .ac-detail b{display:block;color:#17283f}#ariellaDesktopChat .ac-detail span{color:#7f776b;font-size:14px}.ac-flow-card{max-width:92%;background:#fff;border:1px solid #e2d4b8;border-radius:16px;padding:14px;margin:4px 42px 10px 0}.ac-flow-card strong{display:block;margin-bottom:10px}.ac-flow-options{display:grid;grid-template-columns:1fr 1fr;gap:8px}.ac-flow-option{border:1px solid #dccb9f;border-radius:11px;padding:11px;background:#fffaf2;cursor:pointer;text-align:center}.ac-flow-go{margin-top:12px;border:0;border-radius:10px;background:#0b8f9c;color:#fff;font-weight:800;padding:11px 16px}@media(max-width:899px){#ariellaDesktopChat{width:100%;margin:0 auto 24px;padding:8px 10px}#ariellaDesktopChat .ac-shell{display:flex;flex-direction:column}#ariellaDesktopChat .ac-chat{height:calc(100dvh - 125px);min-height:500px;border-radius:16px}#ariellaDesktopChat .ac-online{display:none}#ariellaDesktopChat .ac-summary{border-radius:16px}.ac-flow-card{margin-right:0;max-width:100%}}@media(max-width:380px){#ariellaDesktopChat .ac-head-copy strong{font-size:14.5px}#ariellaDesktopChat .ac-avatar{width:48px;height:48px;flex-basis:48px}}`;document.head.appendChild(s);}
function makeChat(){let c=document.getElementById('ariellaDesktopChat');if(c)return c;const defs=[['destination','יעד'],['dates','תאריכים'],['travelers','נוסעים'],['budget','תקציב'],['flight','טיסה'],['baggage','כבודה']];c=document.createElement('section');c.id='ariellaDesktopChat';c.innerHTML='<div class="ac-shell"><div class="ac-chat"><div class="ac-head"><div class="ac-avatar"></div><div class="ac-head-copy"><strong>אריאלה — סוכנת הנסיעות האישית שלך</strong></div><div class="ac-online">זמינה עכשיו</div></div><div class="ac-messages" id="ariellaChatMessages"></div><div class="ac-compose"><textarea id="ariellaChatInput" rows="1"></textarea><button id="ariellaChatSend" class="ac-send" type="button">שליחה</button></div></div><aside class="ac-summary"><strong>החופשה שלי</strong>'+defs.map(d=>'<div class="ac-detail" data-summary-key="'+d[0]+'"><b>'+d[1]+'</b><span>עדיין לא צוין</span></div>').join('')+'</aside></div>';const w=document.getElementById('tripWizard'),m=document.querySelector('main');if(w&&w.parentNode)w.parentNode.insertBefore(c,w);else if(m)m.appendChild(c);return c;}
function loadAvatar(){fetch('/static/ariella-avatar-runtime-20260913.js?avatar_source='+FLOW,{cache:'no-store'}).then(r=>r.text()).then(js=>{const m=js.match(/const\s+src\s*=\s*'([^']+)'/);if(!m)return;const src=m[1];document.querySelectorAll('#ariellaDesktopChat .ac-avatar,#ariellaDesktopChat .ac-mini-avatar').forEach(el=>{el.textContent='';el.style.setProperty('background-image','url("'+src+'")','important');el.style.setProperty('background-position','center 35%','important');el.style.setProperty('background-size','115% auto','important');el.style.setProperty('background-repeat','no-repeat','important');});}).catch(()=>{});}
function controller(chat){if(chat.dataset.ctrl==='1')return;chat.dataset.ctrl='1';const input=chat.querySelector('#ariellaChatInput'),send=chat.querySelector('#ariellaChatSend'),messages=chat.querySelector('#ariellaChatMessages');let profile={},history=[],busy=false;try{const s=JSON.parse(localStorage.getItem('ariellaChatState:v4')||'null');if(s){profile=s.profile||{};history=Array.isArray(s.history)?s.history:[];}}catch(e){}
const save=()=>{try{localStorage.setItem('ariellaChatState:v4',JSON.stringify({profile,history:history.slice(-120),saved_at:new Date().toISOString()}));}catch(e){}};
const add=(who,text)=>{if(!String(text||'').trim())return;const r=document.createElement('div');r.className='ac-row '+who;if(who==='bot'){const a=document.createElement('div');a.className='ac-mini-avatar';r.appendChild(a);}const b=document.createElement('div');b.className='ac-bubble';b.textContent=text;r.appendChild(b);messages.appendChild(r);messages.scrollTop=messages.scrollHeight;};
const summary=()=>{const p=profile,v={destination:Array.isArray(p.destinations)?p.destinations.join(', '):(p.destinations||''),dates:p.departure_date&&p.return_date?p.departure_date+' – '+p.return_date:(p.outbound_month||p.return_month||''),travelers:(p.adults||p.children||p.infants)?`${p.adults||0} מבוגרים${p.children?`, ${p.children} ילדים`:''}${p.infants?`, ${p.infants} תינוקות`:''}`:'',budget:p.budget_mode==='unlimited'?'ללא הגבלת תקציב':(p.budget_amount?`${p.budget_amount} ₪ לאדם`:''),flight:p.flight_preference||'',baggage:p.baggage||''};Object.keys(v).forEach(k=>{const s=chat.querySelector(`[data-summary-key="${k}"] span`);if(s)s.textContent=v[k]||'עדיין לא צוין';});};
function purpose(){const card=document.createElement('div');card.className='ac-flow-card';card.innerHTML='<strong>איזה סוג חופשה תרצו לתכנן?</strong><div class="ac-flow-options"><button class="ac-flow-option" data-v="standard">🏖️ נופש</button><button class="ac-flow-option" data-v="business">💼 טיסת עסקים</button><button class="ac-flow-option" data-v="ski">⛷️ חופשת סקי</button></div>';messages.appendChild(card);card.querySelectorAll('button').forEach(b=>b.onclick=async()=>{profile.vacation_type=b.dataset.v;card.remove();if(profile.vacation_type==='standard'){profile.services=['flight'];add('bot',OPENING);history.push({role:'assistant',content:OPENING});save();loadAvatar();}else{await sendMessage(profile.vacation_type==='business'?'אני מחפש/ת טיסת עסקים':'אני מחפש/ת חופשת סקי',false);}});}
async function sendMessage(raw,display){raw=String(raw||'').trim();if(!raw||busy)return;busy=true;send.disabled=true;if(display)add('user',raw);const prior=history.slice(-12);history.push({role:'user',content:raw});save();try{const payload={message:raw,history:prior,profile};const r=await fetch('/api/ariella/chat',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});let data={};try{data=await r.json();}catch(e){}if(!r.ok||data.status!=='success'){add('bot',data.message||'יש כרגע תקלה זמנית. נסי שוב בעוד רגע.');return;}profile=data.profile||profile;summary();const reply=String(data.reply||'').trim();if(reply){add('bot',reply);history.push({role:'assistant',content:reply});}save();loadAvatar();}catch(e){add('bot','יש כרגע תקלה זמנית. נסי שוב בעוד רגע.');}finally{busy=false;send.disabled=false;input.value='';input.focus();}}
send.addEventListener('click',e=>{e.preventDefault();sendMessage(input.value,true);});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage(input.value,true);}});messages.innerHTML='';if(history.length){history.forEach(x=>add(x.role==='assistant'?'bot':'user',x.content));}else purpose();summary();}
function patchFetch(){if(window.__ariellaPatched)return;window.__ariellaPatched=true;const old=window.fetch.bind(window);window.fetch=async function(input,init){const url=typeof input==='string'?input:(input&&input.url)||'';if(/\/api\/ariella\/chat(?:\?|$)/.test(url)&&init&&typeof init.body==='string'){try{const p=JSON.parse(init.body),m=String(p.message||'').trim();if(m)p.message='הודעת הלקוח המקורית:\n'+m+'\n\n'+RULES;init=Object.assign({},init,{body:JSON.stringify(p)});}catch(e){}}return old(input,init);};}
function boot(){if(!isTrip())return;removeLegacy();style();patchFetch();const chat=makeChat();loadAvatar();controller(chat);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();